for i in range(0, len(documents), 3):
    batch = documents[i : i + 3]
    batch_text = ""

    for f in batch:
        doc_data = f.json
        doc_name = doc_data.get('doc_name', 'Unknown Doc')
        notes = doc_data.get('metadata', {}).get('Notes', '')
        batch_text += f"---\n\nDocument: {doc_name}\n"
        for cat in categories:
            cat_data = cat.json
            refs = cat_data.get('metadata', {}).get('references', [])
            ref_doc_names = [r.get('document') for r in refs]
            if doc_name in ref_doc_names:
                index = cat_data.get('metadata', {}).get('index')
                label = cat_data.get('content') # or 'category' based on previous nodes
                inds_list = cat_data.get('metadata', {}).get('indicators', [])
                if isinstance(inds_list, list):
                    indicators = ", ".join(inds_list)
                else:
                    indicators = str(inds_list)

                batch_text += f"{index}. {label}: {indicators}\n"

        batch_text += f"\nTheoretical questions: {notes}\n"

    output_list.append({
        "json": {
            "content": batch_text
        }
    })

return output_list

