import random

# Initialize the master hierarchy
hierarchy = {}

# 1. Collect ALL documents first
for i in _input.all():
    data = i.to_py()["json"]
    doc_name = data["doc_name"]
    groups = data["metadata"]["comparison_groups"]

    for variable, category_value in groups.items():
        if variable not in hierarchy:
            hierarchy[variable] = {}
        if category_value not in hierarchy[variable]:
            hierarchy[variable][category_value] = []

        hierarchy[variable][category_value].append(doc_name)

# 2. Downsample to max 5 random documents per group
for variable in hierarchy:
    for category in hierarchy[variable]:
        doc_list = hierarchy[variable][category]

        if len(doc_list) > 5:
            # Pick 5 random unique items
            hierarchy[variable][category] = random.sample(doc_list, 5)
        # Else: leave the list as is (it has 5 or fewer)

return hierarchy

